-- wallet_status_history: Immutable history of wallet status changes
CREATE TABLE wallet_status_history (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  wallet_id                    uuid NOT NULL REFERENCES wallet(id),
  from_status                  varchar(40) CHECK (from_status IN ('PENDING', 'ACTIVE', 'DORMANT', 'SUSPENDED', 'BLOCKED', 'CLOSED')),
  to_status                    varchar(40) NOT NULL CHECK (to_status IN ('PENDING', 'ACTIVE', 'DORMANT', 'SUSPENDED', 'BLOCKED', 'CLOSED')),
  reason                       varchar(255),
  changed_by                   varchar(64),
  approval_request_id          uuid,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
COMMENT ON TABLE wallet_status_history IS 'Immutable history of wallet status changes';
COMMENT ON COLUMN wallet_status_history.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN wallet_status_history.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN wallet_status_history.created_at IS 'Creation time';
COMMENT ON COLUMN wallet_status_history.created_by IS 'Principal that created the row';
COMMENT ON COLUMN wallet_status_history.wallet_id IS 'Wallet';
COMMENT ON COLUMN wallet_status_history.from_status IS 'Previous status';
COMMENT ON COLUMN wallet_status_history.to_status IS 'New status';
COMMENT ON COLUMN wallet_status_history.reason IS 'Reason';
COMMENT ON COLUMN wallet_status_history.changed_by IS 'Principal';
COMMENT ON COLUMN wallet_status_history.approval_request_id IS 'Maker-checker approval';
COMMENT ON COLUMN wallet_status_history.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN wallet_status_history.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN wallet_status_history.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN wallet_status_history.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN wallet_status_history.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_wallet_status_history_tenant ON wallet_status_history (tenant_id, created_at);
CREATE INDEX ix_wallet_status_history_wallet_id ON wallet_status_history (wallet_id);
CREATE INDEX ix_wallet_status_history_approval_request_id ON wallet_status_history (approval_request_id);
ALTER TABLE wallet_status_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON wallet_status_history USING (tenant_id = current_setting('app.tenant_id')::uuid);
